"""SQLite state: runs, proposals (with decisions) and an audit log of every CRM write.

Idempotency rules
-----------------
Each proposal has a fingerprint = hash(kind, subject, the field values it would
write). Notes, evidence and dates are excluded, so the same finding produces
the same fingerprint every day.

  * fingerprint already applied or rejected  -> suppressed, never re-proposed
  * fingerprint already pending              -> kept as is (evidence refreshed)
  * fingerprint previously failed or stale   -> reopened as pending
  * pending proposal not regenerated by a run -> marked obsolete (the CRM or
    the website changed, so the finding no longer applies)
"""
import json
import os
import sqlite3
from datetime import datetime, timezone

DECIDED = ("applied", "rejected")
REOPENABLE = ("failed", "stale")

SCHEMA = """
CREATE TABLE IF NOT EXISTS runs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    started_at TEXT NOT NULL,
    finished_at TEXT,
    ok INTEGER DEFAULT 0,
    stats TEXT DEFAULT '{}',
    report TEXT DEFAULT '{}'
);
CREATE TABLE IF NOT EXISTS proposals (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    fingerprint TEXT NOT NULL UNIQUE,
    kind TEXT NOT NULL,
    subject TEXT NOT NULL,
    title TEXT NOT NULL,
    summary TEXT NOT NULL,
    payload TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',
    created_run INTEGER,
    last_seen_run INTEGER,
    created_at TEXT,
    decided_at TEXT,
    decided_by TEXT,
    reviewer_comment TEXT,
    applied_at TEXT,
    progress INTEGER NOT NULL DEFAULT 0,
    context TEXT NOT NULL DEFAULT '{}',
    error TEXT
);
CREATE INDEX IF NOT EXISTS ix_proposals_status ON proposals(status);
CREATE TABLE IF NOT EXISTS audit (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ts TEXT NOT NULL,
    proposal_id INTEGER,
    actor TEXT,
    action TEXT NOT NULL,
    target TEXT,
    request TEXT,
    response TEXT,
    ok INTEGER
);
"""


def now():
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%SZ")


class Store:
    def __init__(self, path: str):
        if path != ":memory:":
            os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
        self.db = sqlite3.connect(path, check_same_thread=False)
        self.db.row_factory = sqlite3.Row
        self.db.executescript(SCHEMA)
        self.db.commit()

    # ------------------------------------------------------------- runs
    def start_run(self) -> int:
        cur = self.db.execute("INSERT INTO runs(started_at) VALUES (?)", (now(),))
        self.db.commit()
        return cur.lastrowid

    def finish_run(self, run_id, ok, stats, report):
        self.db.execute(
            "UPDATE runs SET finished_at=?, ok=?, stats=?, report=? WHERE id=?",
            (now(), int(ok), json.dumps(stats), json.dumps(report), run_id))
        self.db.commit()

    def last_ok_run(self, before_id=None):
        q = "SELECT * FROM runs WHERE ok=1"
        args = ()
        if before_id:
            q += " AND id < ?"
            args = (before_id,)
        row = self.db.execute(q + " ORDER BY id DESC LIMIT 1", args).fetchone()
        return self._run(row)

    def runs(self, limit=20):
        rows = self.db.execute("SELECT * FROM runs ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
        return [self._run(r) for r in rows]

    @staticmethod
    def _run(row):
        if not row:
            return None
        d = dict(row)
        d["stats"] = json.loads(d["stats"] or "{}")
        d["report"] = json.loads(d["report"] or "{}")
        return d

    # ------------------------------------------------------------- proposals
    def upsert_proposal(self, run_id, p) -> str:
        """Insert or reconcile one generated proposal. Returns the outcome."""
        payload = json.dumps({k: p[k] for k in ("ops", "changes", "evidence", "warnings")})
        row = self.db.execute("SELECT id, status FROM proposals WHERE fingerprint=?",
                              (p["fingerprint"],)).fetchone()
        if row is None:
            self.db.execute(
                """INSERT INTO proposals(fingerprint, kind, subject, title, summary, payload,
                   status, created_run, last_seen_run, created_at)
                   VALUES (?,?,?,?,?,?, 'pending', ?, ?, ?)""",
                (p["fingerprint"], p["kind"], p["subject"], p["title"], p["summary"],
                 payload, run_id, run_id, now()))
            outcome = "new"
        elif row["status"] in DECIDED or row["status"] == "approved":
            self.db.execute("UPDATE proposals SET last_seen_run=? WHERE id=?", (run_id, row["id"]))
            outcome = "suppressed"
        elif row["status"] == "failed":
            # Same finding, a write already partly done: keep progress and created ids so the next
            # approval resumes where it stopped instead of starting over.
            self.db.execute(
                "UPDATE proposals SET status='pending', title=?, summary=?, last_seen_run=? WHERE id=?",
                (p["title"], p["summary"], run_id, row["id"]))
            outcome = "reopened"
        elif row["status"] in REOPENABLE or row["status"] == "obsolete":
            self.db.execute(
                """UPDATE proposals SET status='pending', title=?, summary=?, payload=?,
                   last_seen_run=?, progress=0, context='{}', error=NULL WHERE id=?""",
                (p["title"], p["summary"], payload, run_id, row["id"]))
            outcome = "reopened"
        else:  # pending: refresh the evidence, keep the decision slot
            self.db.execute(
                "UPDATE proposals SET title=?, summary=?, payload=?, last_seen_run=? WHERE id=?",
                (p["title"], p["summary"], payload, run_id, row["id"]))
            outcome = "kept"
        self.db.commit()
        return outcome

    def obsolete_unseen(self, run_id) -> int:
        cur = self.db.execute(
            "UPDATE proposals SET status='obsolete' WHERE status='pending' AND last_seen_run < ?",
            (run_id,))
        self.db.commit()
        return cur.rowcount

    def get(self, pid):
        row = self.db.execute("SELECT * FROM proposals WHERE id=?", (pid,)).fetchone()
        return self._prop(row)

    def list(self, statuses=None):
        if statuses:
            marks = ",".join("?" * len(statuses))
            rows = self.db.execute(
                f"SELECT * FROM proposals WHERE status IN ({marks}) ORDER BY id", tuple(statuses)).fetchall()
        else:
            rows = self.db.execute("SELECT * FROM proposals ORDER BY id").fetchall()
        return [self._prop(r) for r in rows]

    def counts(self):
        rows = self.db.execute("SELECT status, COUNT(*) n FROM proposals GROUP BY status").fetchall()
        return {r["status"]: r["n"] for r in rows}

    def next_pending(self, after_id=0):
        row = self.db.execute(
            "SELECT id FROM proposals WHERE status='pending' AND id > ? ORDER BY id LIMIT 1",
            (after_id,)).fetchone()
        if row is None:
            row = self.db.execute(
                "SELECT id FROM proposals WHERE status='pending' ORDER BY id LIMIT 1").fetchone()
        return row["id"] if row else None

    def set_status(self, pid, status, **fields):
        cols = {"status": status, **fields}
        sets = ", ".join(f"{k}=?" for k in cols)
        self.db.execute(f"UPDATE proposals SET {sets} WHERE id=?", (*cols.values(), pid))
        self.db.commit()

    def save_progress(self, pid, progress, context):
        self.db.execute("UPDATE proposals SET progress=?, context=? WHERE id=?",
                        (progress, json.dumps(context), pid))
        self.db.commit()

    @staticmethod
    def _prop(row):
        if not row:
            return None
        d = dict(row)
        d.update(json.loads(d.pop("payload")))
        d["context"] = json.loads(d["context"] or "{}")
        return d

    # ------------------------------------------------------------- audit
    def audit(self, proposal_id, actor, action, target, request=None, response=None, ok=True):
        self.db.execute(
            """INSERT INTO audit(ts, proposal_id, actor, action, target, request, response, ok)
               VALUES (?,?,?,?,?,?,?,?)""",
            (now(), proposal_id, actor, action, target,
             json.dumps(request, default=str) if request is not None else None,
             json.dumps(response, default=str) if response is not None else None, int(ok)))
        self.db.commit()

    def audit_log(self, proposal_id=None, limit=500):
        if proposal_id is None:
            rows = self.db.execute("SELECT * FROM audit ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
        else:
            rows = self.db.execute("SELECT * FROM audit WHERE proposal_id=? ORDER BY id",
                                   (proposal_id,)).fetchall()
        return [dict(r) for r in rows]
